/**
 * Bruno's own voice for the things that go wrong (ARCHITECTURE.md §6.1, NFR-09, UC-22).
 *
 * The child screen never shows text, so a failure has to be *heard*. The server sends a
 * code; this maps it to one of the three lines in UI.md §5 and plays a file that was
 * synthesized ahead of time, so it still works when the very service that failed is the
 * one that would have spoken.
 *
 * The files are generated by `make audio` into public/audio and are **not committed**:
 * the only Serbian voice available is non-commercial (docs/CLAUDE.md §3), so its audio
 * cannot live in the repository either. A checkout without them is not broken - the
 * character simply settles back to idle, which is still no text and no error screen.
 */

export type FallbackLine = 'hold_paw' | 'not_heard' | 'fallback';

/** Server error codes (EVALUATION.md §4.1) mapped to what the child should hear. */
const LINES: Record<string, FallbackLine> = {
  hold_paw: 'hold_paw',
  stt_empty: 'not_heard',
  stt_failed: 'not_heard',
  llm_failed: 'fallback',
  llm_timeout: 'fallback',
  tts_failed: 'fallback',
  filter_blocked: 'fallback',
  queue_timeout: 'fallback',
  rate_limited: 'fallback',
  interrupted: 'fallback',
};

export function lineFor(code: string): FallbackLine {
  return LINES[code] ?? 'fallback';
}

export class FallbackVoice {
  private cache = new Map<string, AudioBuffer>();
  private missing = new Set<string>();

  constructor(
    private readonly context: AudioContext,
    private readonly language: string,
  ) {}

  /** Play the line for a code. Silent, never an error, if the file is not there. */
  async play(code: string): Promise<boolean> {
    const line = lineFor(code);
    const key = `${this.language}/${line}`;
    if (this.missing.has(key)) return false;

    let buffer = this.cache.get(key);
    if (buffer === undefined) {
      try {
        const response = await fetch(`/audio/${key}.wav`);
        if (!response.ok) throw new Error(String(response.status));
        buffer = await this.context.decodeAudioData(await response.arrayBuffer());
        this.cache.set(key, buffer);
      } catch {
        // generated locally by `make audio`; a checkout without them stays quiet
        this.missing.add(key);
        return false;
      }
    }
    const source = this.context.createBufferSource();
    source.buffer = buffer;
    source.connect(this.context.destination);
    source.start();
    return true;
  }

  /** Fetch them up front, so the first failure is not also the first download. */
  async warm(): Promise<void> {
    await Promise.all(
      (['hold_paw', 'not_heard', 'fallback'] as FallbackLine[]).map(async (line) => {
        const key = `${this.language}/${line}`;
        if (this.cache.has(key) || this.missing.has(key)) return;
        try {
          const response = await fetch(`/audio/${key}.wav`);
          if (!response.ok) throw new Error(String(response.status));
          this.cache.set(key, await this.context.decodeAudioData(await response.arrayBuffer()));
        } catch {
          this.missing.add(key);
        }
      }),
    );
  }
}
